import json
import sys
import pandas as pd
import numpy as np

# Load input
with open(sys.argv[1]) as f:
    data = json.load(f)

portfolio = data['portfolio']
market_data = data['market_data']
sector_map = data['sector_map']

# Build weights dict
holdings = portfolio['holdings']
weights = {h['symbol']: h['weight'] for h in holdings}
w_series = pd.Series(weights)

# Normalize weights
total_w = sum(weights.values())
weights_norm = {k: v/total_w for k, v in weights.items()}
w_norm = pd.Series(weights_norm)

risk_exposures = []

# 1. Sector concentration
sector_weights = {}
for sym, sector in sector_map.items():
    if sym in weights_norm:
        sector_weights[sector] = sector_weights.get(sector, 0) + weights_norm[sym]

for sector, sw in sorted(sector_weights.items(), key=lambda x: -x[1]):
    risk_exposures.append({
        'type': 'sector_concentration',
        'detail': f'{sector} sector concentration',
        'magnitude': round(sw, 4)
    })

# 2. Single stock concentration (top holdings)
for sym, w in sorted(weights_norm.items(), key=lambda x: -x[1]):
    if w > 0.05:
        risk_exposures.append({
            'type': 'single_stock_concentration',
            'detail': f'{sym} position concentration',
            'magnitude': round(w, 4)
        })

# 3. Factor exposures
try:
    factor_exp = pd.read_parquet(market_data['factor_exposures'])
    syms_in = [s for s in weights_norm if s in factor_exp.index]
    if syms_in:
        w_sub = pd.Series({s: weights_norm[s] for s in syms_in})
        w_sub = w_sub / w_sub.sum()
        port_factor = factor_exp.loc[syms_in].multiply(w_sub, axis=0).sum()
        for factor, val in port_factor.items():
            risk_exposures.append({
                'type': 'factor_exposure',
                'detail': f'{factor} factor exposure',
                'magnitude': round(float(val), 4)
            })
except Exception as e:
    pass

# 4. Portfolio volatility and correlation
try:
    returns = pd.read_parquet(market_data['returns'])
    avail = [s for s in weights_norm if s in returns.columns]
    if avail:
        ret_sub = returns[avail].dropna()
        w_arr = np.array([weights_norm[s] for s in avail])
        w_arr = w_arr / w_arr.sum()
        cov = ret_sub.cov() * 252
        port_var = w_arr @ cov.values @ w_arr
        port_vol = float(np.sqrt(port_var))
        risk_exposures.append({
            'type': 'portfolio_volatility',
            'detail': 'Annualized portfolio volatility',
            'magnitude': round(port_vol, 4)
        })
        # Correlation risk
        corr = ret_sub.corr()
        n = len(avail)
        avg_corr = (corr.values.sum() - n) / (n * (n-1)) if n > 1 else 0
        risk_exposures.append({
            'type': 'correlation_risk',
            'detail': 'Average pairwise correlation among holdings',
            'magnitude': round(float(avg_corr), 4)
        })
        # Individual stock vols
        for sym in avail:
            vol = float(np.sqrt(ret_sub[sym].var() * 252))
            risk_exposures.append({
                'type': 'stock_volatility',
                'detail': f'{sym} annualized volatility',
                'magnitude': round(vol, 4)
            })
except Exception as e:
    pass

# Sort by magnitude descending
risk_exposures.sort(key=lambda x: abs(x['magnitude']), reverse=True)

# Rank top exposures
top_risks = []
for i, r in enumerate(risk_exposures[:10], 1):
    top_risks.append({
        'rank': i,
        'type': r['type'],
        'detail': r['detail'],
        'magnitude': r['magnitude']
    })

print(json.dumps({'top_risk_exposures': top_risks}))

