import json, sys, pandas as pd, numpy as np
with open(sys.argv[1]) as f: data = json.load(f)
holdings = data['portfolio']['holdings']
sector_map = data['sector_map']
factor_path = data['factor_exposures_path']
returns_path = data['returns_path']
weights = {h['symbol']: h['weight'] for h in holdings}
total_weight = sum(weights.values())
if abs(total_weight - 1.0) > 0.01: weights = {k: v/total_weight for k, v in weights.items()}
sector_weights = {}
for sym, w in weights.items():
    sec = sector_map.get(sym, 'Unknown')
    sector_weights[sec] = sector_weights.get(sec, 0) + w
try:
    fe = pd.read_parquet(factor_path)
    fe_info = {'cols': fe.columns.tolist(), 'shape': list(fe.shape), 'head': fe.head(2).to_dict()}
except Exception as e:
    fe_info = {'error': str(e)}
try:
    ret = pd.read_parquet(returns_path)
    ret_info = {'cols': ret.columns.tolist()[:20], 'shape': list(ret.shape)}
except Exception as e:
    ret_info = {'error': str(e)}
print(json.dumps({'sector_weights': sector_weights, 'fe_info': fe_info, 'ret_info': ret_info}))

